const crypto = require('crypto');

const callbackBase = $env.CALLBACK_URL;
const secret = $env.N8N_CALLBACK_SECRET;

const runLogId = $('Webhook').first().json.body.runLogId;

const errorMessage =
  $json.errorMessage ||
  $json.error ||
  'GPT error';

const payload = {
  runLogId,
  errorMessage: String(errorMessage).slice(0, 4000),
  status: "error",
  idempotencyKey: `${runLogId}:gpt_prompt:final:error`,
  rawPayload: {
    source: 'n8n',
    node: 'gpt_prompt-final-error-callback',
    at: new Date().toISOString(),
  },
};

const body = JSON.stringify(payload);
const signature = crypto.createHmac('sha256', secret).update(body).digest('hex');

return {
  json: {
    url: `${callbackBase.replace(/\/+$/, '')}/n8n/callback`,
    body,
    signature,
    payload
  }
};

