const crypto = require('crypto');

const promptTokens = $('GPT PROMPT').first().json?.usage?.prompt_tokens ?? 0;
const completionTokens = $('GPT PROMPT').first().json?.usage?.completion_tokens ?? 0;
const soraSeconds = $('Webhook').first().json?.body?.parameters?.seconds ?? 0;
const runLogId = $('Webhook').first().json?.body?.runLogId;

if (!runLogId) {
  throw new Error('runLogId is required');
}

const callbackBase = String($env.CALLBACK_URL || '').replace(/\/+$/, '');
const secret = String($env.N8N_CALLBACK_SECRET || '');

if (!callbackBase || !secret) {
  throw new Error('CALLBACK_URL or N8N_CALLBACK_SECRET is missing');
}

const payload = {
  runLogId,
  status: 'success',
  idempotencyKey: `${runLogId}:final:success:v1`,
  usageLineItems: [
    { meterCode: 'gpt_prompt', qty: Number(promptTokens) },
    { meterCode: 'gpt_completion', qty: Number(completionTokens) },
    { meterCode: 'sora_seconds', qty: Number(soraSeconds) },
  ],
  outputUrl: $('SAVE VIDEO').first().json?.originalUrl ?? null,
  rawPayload: {
    fileId: $('SAVE VIDEO').first().json?.id ?? null,
    provider: 'openai_sora',
    model: 'sora-2',
  },
};

const body = JSON.stringify(payload);
const signature = crypto
  .createHmac('sha256', secret)
  .update(body)
  .digest('hex');

return {
  json: {
    url: `${callbackBase}/n8n/callback`,
    body,
    signature,
    payload,
  },
};

